-- RANGE frames with offsets over an order key whose NULL group comes first:
-- a NULL row frames its NULL peers, a valid row only valid rows.
SELECT id, k, i32, count(*) OVER (PARTITION BY k ORDER BY i32 ASC NULLS FIRST RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS c_asc, sum(id) OVER (PARTITION BY k ORDER BY i32 DESC NULLS FIRST RANGE BETWEEN 2 PRECEDING AND CURRENT ROW) AS s_desc, count(*) OVER (PARTITION BY k ORDER BY i32 ASC NULLS FIRST RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS c_before FROM nulls WHERE id < 300 ORDER BY id ASC NULLS LAST
